import { IngestPipeline, Key, MaterializedView, Api, sql } from "@514labs/moose-lib";

// Product Event Data Model
export interface ProductEvent {
  event_id: Key<string>;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: "view" | "cart" | "purchase";
  properties: Record<string, any>;
}

// Ingestion Pipeline - creates API endpoint, stream, and table
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  ingestApi: true, // Creates POST /ingest/ProductEvent
  stream: true,    // Buffers data through Kafka/Redpanda
  table: {         // Creates ClickHouse table
    orderByFields: ["event_id", "user_id", "event_ts"] // Primary key (event_id) must be first
  }
});

// Get the table reference for materialized views
const productEventsTable = ProductEventPipeline.table!;

// 1. Top Products Aggregation
export interface TopProductsView {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
}

export const TopProductsMV = new MaterializedView<TopProductsView>({
  tableName: "TopProducts",
  materializedViewName: "TopProducts_MV",
  orderByFields: ["product_id"],
  selectTables: [productEventsTable],
  selectStatement: sql`
    SELECT
      product_id,
      countIf(event_type = 'view') AS view_count,
      countIf(event_type = 'cart') AS cart_count,
      countIf(event_type = 'purchase') AS purchase_count,
      sumIf(
        COALESCE(CAST(JSONExtractFloat(properties, 'price') AS Float64), 0),
        event_type = 'purchase'
      ) AS total_revenue
    FROM ${productEventsTable}
    GROUP BY product_id
  `,
});

// 2. Conversion Funnel Aggregation
export interface ConversionFunnelView {
  funnel_date: Date;
  unique_viewers: number;
  unique_carters: number;
  unique_purchasers: number;
  total_views: number;
  total_carts: number;
  total_purchases: number;
}

export const ConversionFunnelMV = new MaterializedView<ConversionFunnelView>({
  tableName: "ConversionFunnel",
  materializedViewName: "ConversionFunnel_MV",
  orderByFields: ["funnel_date"],
  selectTables: [productEventsTable],
  selectStatement: sql`
    SELECT
      toStartOfDay(event_ts) AS funnel_date,
      uniqIf(user_id, event_type = 'view') AS unique_viewers,
      uniqIf(user_id, event_type = 'cart') AS unique_carters,
      uniqIf(user_id, event_type = 'purchase') AS unique_purchasers,
      countIf(event_type = 'view') AS total_views,
      countIf(event_type = 'cart') AS total_carts,
      countIf(event_type = 'purchase') AS total_purchases
    FROM ${productEventsTable}
    GROUP BY funnel_date
  `,
});

// 3. Hourly Activity Aggregation
export interface HourlyActivityView {
  activity_hour: Date;
  event_type: string;
  event_count: number;
}

export const HourlyActivityMV = new MaterializedView<HourlyActivityView>({
  tableName: "HourlyActivity",
  materializedViewName: "HourlyActivity_MV",
  orderByFields: ["activity_hour", "event_type"],
  selectTables: [productEventsTable],
  selectStatement: sql`
    SELECT
      toStartOfHour(event_ts) AS activity_hour,
      event_type,
      count() AS event_count
    FROM ${productEventsTable}
    GROUP BY activity_hour, event_type
  `,
});

// Consumption APIs

// Top Products API
export const TopProductsApi = new Api<{}, TopProductsView[]>(
  "top-products",
  async ({}, { client, sql }) => {
    const result = await client.query.execute<TopProductsView>(sql`
      SELECT *
      FROM TopProducts
      ORDER BY total_revenue DESC, purchase_count DESC
      LIMIT 50
    `);
    return result.json();
  }
);

// Conversion Funnel API
interface FunnelParams {
  startDate?: string;
  endDate?: string;
}

export const ConversionFunnelApi = new Api<FunnelParams, ConversionFunnelView[]>(
  "conversion-funnel",
  async ({ startDate, endDate }, { client, sql }) => {
    let whereClause = '';
    if (startDate && endDate) {
      whereClause = `WHERE funnel_date BETWEEN '${startDate}' AND '${endDate}'`;
    } else if (startDate) {
      whereClause = `WHERE funnel_date >= '${startDate}'`;
    } else if (endDate) {
      whereClause = `WHERE funnel_date <= '${endDate}'`;
    }

    const result = await client.query.execute<ConversionFunnelView>(sql`
      SELECT *
      FROM ConversionFunnel
      ${whereClause}
      ORDER BY funnel_date DESC
    `);
    return result.json();
  }
);

// Hourly Activity API
interface ActivityParams {
  hours?: number;
}

export const HourlyActivityApi = new Api<ActivityParams, HourlyActivityView[]>(
  "hourly-activity",
  async ({ hours = 24 }, { client, sql }) => {
    const result = await client.query.execute<HourlyActivityView>(sql`
      SELECT *
      FROM HourlyActivity
      WHERE activity_hour >= NOW() - INTERVAL ${hours} HOUR
      ORDER BY activity_hour DESC, event_type
    `);
    return result.json();
  }
);

