const http = require('http');
const { exec } = require('child_process');

// Simple analytics server to serve aggregated data
const server = http.createServer(async (req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Origin', '*');

  const url = new URL(req.url, `http://${req.headers.host}`);
  const startTime = Date.now();

  try {
    let query;
    let endpoint;

    switch (url.pathname) {
      case '/api/top-products':
        endpoint = 'top-products';
        query = 'SELECT * FROM TopProductsView';
        break;

      case '/api/conversion-funnel':
        endpoint = 'conversion-funnel';
        const startDate = url.searchParams.get('startDate');
        const endDate = url.searchParams.get('endDate');

        query = 'SELECT * FROM ConversionFunnelView';
        if (startDate && endDate) {
          query += ` WHERE funnel_date BETWEEN '${startDate}' AND '${endDate}'`;
        } else if (startDate) {
          query += ` WHERE funnel_date >= '${startDate}'`;
        } else if (endDate) {
          query += ` WHERE funnel_date <= '${endDate}'`;
        }
        query += ' ORDER BY funnel_date DESC';
        break;

      case '/api/hourly-activity':
        endpoint = 'hourly-activity';
        const hours = url.searchParams.get('hours') || '24';
        query = `
          SELECT * FROM HourlyActivityView
          WHERE activity_hour >= NOW() - INTERVAL ${hours} HOUR
          ORDER BY activity_hour DESC, event_type
        `;
        break;

      case '/health':
        res.writeHead(200);
        res.end(JSON.stringify({
          status: 'healthy',
          uptime: process.uptime(),
          timestamp: new Date().toISOString()
        }));
        return;

      default:
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Endpoint not found' }));
        return;
    }

    // Execute the query via moose CLI
    exec(`moose query "${query}"`, { cwd: '/workspace/moose-project' }, (error, stdout, stderr) => {
      const responseTime = Date.now() - startTime;

      if (error) {
        console.error(`Query error for ${endpoint}:`, error);
        res.writeHead(500);
        res.end(JSON.stringify({
          error: 'Database query failed',
          message: error.message,
          responseTime: responseTime + 'ms'
        }));
        return;
      }

      try {
        // Parse the moose query output to extract JSON data
        const lines = stdout.trim().split('\n');
        const dataLines = lines.filter(line => line.startsWith('{"'));
        const results = dataLines.map(line => JSON.parse(line));

        res.writeHead(200);
        res.end(JSON.stringify({
          endpoint,
          data: results,
          count: results.length,
          responseTime: responseTime + 'ms',
          timestamp: new Date().toISOString()
        }));
      } catch (parseError) {
        console.error(`Parse error for ${endpoint}:`, parseError);
        res.writeHead(500);
        res.end(JSON.stringify({
          error: 'Failed to parse query results',
          rawOutput: stdout,
          responseTime: responseTime + 'ms'
        }));
      }
    });

  } catch (err) {
    const responseTime = Date.now() - startTime;
    console.error('Server error:', err);
    res.writeHead(500);
    res.end(JSON.stringify({
      error: 'Internal server error',
      message: err.message,
      responseTime: responseTime + 'ms'
    }));
  }
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`Analytics API server running on http://localhost:${PORT}`);
  console.log('Available endpoints:');
  console.log('  GET /api/top-products');
  console.log('  GET /api/conversion-funnel?startDate=YYYY-MM-DD&endDate=YYYY-MM-DD');
  console.log('  GET /api/hourly-activity?hours=24');
  console.log('  GET /health');
});

